snippet_css:
:root{
  --bg: #EBD5B3;
  --fg: #3A2718;
  --muted: #5C4128;
  --surface: #F6EAD4;
  --border: #C9A97C;
  --accent: #8E3B26;
  --accent-fg: #FFFFFF;
  --radius: 8px;
  --radius-sm: 5px;
  --shadow: 0 6px 0 rgba(58,39,24,.18);
  --btn-shadow: 0 4px 0 #6E2E1E;
  --art-bg: radial-gradient(circle at 50% 100%,#F2B84B 0 22%,transparent 23%),linear-gradient(#C1633B,#8E3B26 60%,#3A2718 61%);
  --media-bg: linear-gradient(#C1633B,#8E3B26 70%,#3A2718 70%);
  --cta-bg: #F2E3C6;
  --input-bg: #FBF3E4;
  --ok: #2F7D63;
  --warn: #A83A22;
  --font-display: 'Alfa Slab One','Noto Sans TC',serif;
  --font-body: 'Merriweather','Noto Sans TC',serif;
  --font-mono: 'Courier New',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
